<?php defined('_JEXEC') or die;use Joomla\CMS\HTML\HTMLHelper;use Joomla\CMS\Language\Text;use Joomla\CMS\Router\Route;HTMLHelper::_('behavior.multiselect');?><form action="<?php echo Route::_('index.php?option=com_xdecaroorganizations&view=organizations');?>" method="post" name="adminForm" id="adminForm"><div class="xdecaro-scope"><div class="row g-2 mb-3"><div class="col-md-5"><input type="search" name="filter_search" class="form-control" value="<?php echo $this->escape((string)$this->state->get('filter.search'));?>" placeholder="<?php echo Text::_('JSEARCH_FILTER');?>"></div><div class="col-md-3"><select name="filter_type" class="form-select" onchange="this.form.submit()"><option value=""><?php echo Text::_('COM_XDECAROORGANIZATIONS_ALL_TYPES');?></option><?php foreach(['organization','association','club','federation','company','public_body','school','sponsor','supplier'] as $type):?><option value="<?php echo $type;?>" <?php echo (string)$this->state->get('filter.type')===$type?'selected':'';?>><?php echo Text::_('COM_XDECAROORGANIZATIONS_TYPE_'.strtoupper($type));?></option><?php endforeach;?></select></div><div class="col-md-2"><select name="filter_state" class="form-select" onchange="this.form.submit()"><option value=""><?php echo Text::_('JOPTION_SELECT_PUBLISHED');?></option><option value="1" <?php echo (string)$this->state->get('filter.state')==='1'?'selected':'';?>><?php echo Text::_('JPUBLISHED');?></option><option value="0" <?php echo (string)$this->state->get('filter.state')==='0'?'selected':'';?>><?php echo Text::_('JUNPUBLISHED');?></option></select></div><div class="col-md-2"><button class="btn btn-primary" type="submit"><?php echo Text::_('JSEARCH_FILTER_SUBMIT');?></button></div></div><div class="table-responsive"><table class="table table-striped"><thead><tr><th><input type="checkbox" name="checkall-toggle" onclick="Joomla.checkAll(this)"></th><th><?php echo Text::_('COM_XDECAROORGANIZATIONS_FIELD_NAME');?></th><th><?php echo Text::_('COM_XDECAROORGANIZATIONS_FIELD_TYPE');?></th><th><?php echo Text::_('COM_XDECAROORGANIZATIONS_FIELD_PARENT');?></th><th><?php echo Text::_('JSTATUS');?></th></tr></thead><tbody><?php foreach($this->items as $i=>$item):?><tr><td><?php echo HTMLHelper::_('grid.id',$i,(int)$item->id);?></td><td><a href="<?php echo Route::_('index.php?option=com_xdecaroorganizations&task=organization.edit&id='.(int)$item->id);?>"><?php echo $this->escape($item->name);?></a></td><td><?php echo $this->escape($item->type);?></td><td><?php echo $this->escape((string)$item->parent_name);?></td><td><?php echo (int)$item->state===1?Text::_('JPUBLISHED'):Text::_('JUNPUBLISHED');?></td></tr><?php endforeach;?></tbody></table></div><?php echo $this->pagination->getListFooter();?></div><input type="hidden" name="task" value=""><input type="hidden" name="boxchecked" value="0"><?php echo HTMLHelper::_('form.token');?></form>
